from melite_models import  KnobRow,Model, Variant, Cell, LoraRow, SourceRow, LaneInputs, Genre, ClipType, Quant


class MinimaxMusic3(Model):
    id = 'music3'
    genre = Genre.AUDIO
    label = 'MiniMax Music 3'
    description = 'MiniMax Music 3 text-to-music with lyrics'
    engine = 'comfyui'
    card = 'music'  # the owning card surface
    form = 'form_music'
    source = SourceRow(type='huggingface', repo_id='audio-cpp/MiniMax-Music3-GGUF', filename='MiniMax-Music3-GGUF')
    # weight facts for the CARD renderer — single source
    lane_inputs = LaneInputs(
        unet='minimax_music3_dit_int8_convrot.safetensors',
        text_encoder='minimax_music3_text_encoder_pruned_int8_convrot.safetensors',
        clip_type=ClipType.MINIMAX,
        vae='minimax_music3_dav.safetensors')

    defaults = dict(backend='cuda')
    # the CASCADE GATE (image-edit rework 2026-09-05) — this lane
    # ships a single ComfyUI UNETLoader configuration. The cell states
    # the TRUE quant tier the loader reads (no tier switch today); a
    # future second cell row lands as a real tier (the family grows).
    variants = (
        Variant(id='standard', label='Standard', route='music3', cells=(
            Cell(quant=Quant.INT8, label='INT8 ConvRot', route='music3', vram_peak_gb=20.0),
        )),
    )


    prompt_upscale = (
        'structure: [Genre, Vocal Details, Arrangement]',
        'rules:',
        '- Genre block first: era + region + 2-3 style anchors + tempo in BPM + key if known',
        '- Vocal Details block: gender, register, delivery manner, one signature texture',
        '- Arrangement block: the instrument story front to back — intro, build, drop, outro',
        '- name production adjectives the ear can verify (dusty, wide, brickwalled)',
        '- never write lyric content in the caption — that lives in the lyrics field',
    )
    lyrics_upscale = (
        'structure: [section tags, rhyme, hook law]',
        'rules:',
        '- every section wrapped in [tag]: [verse] [pre-chorus] [chorus] [bridge] [outro]',
        '- keep verses concrete and grounded',
        'the chorus earns the abstraction',
        '- the hook repeats at least once, word-for-word',
        '- short lines sing: 6-9 syllables default, break longer thoughts',
        '- match the section energy to the arrangement block it sits over',
    )

    card_knobs = (
        KnobRow(card='prompt', inject='MiniMaxMusic3TextEncode.0.caption', kind='s'),
        KnobRow(card='lyrics', inject='MiniMaxMusic3TextEncode.0.lyrics', kind='s'),
        KnobRow(card='duration', inject='EmptyMiniMaxMusic3LatentAudio.0.seconds', kind='n'),
        KnobRow(card='seed', inject='KSampler.0.seed', kind='n'),
        # (wired 2026-09-05, mod-audit follow-up — the three knobs the
        # card grew; renderer targets, schema rows, compose reads all
        # landed together: KSampler cfg/steps and the encode cfg_scale)
        KnobRow(card='guidance_scale', inject='KSampler.0.cfg', kind='n'),
        KnobRow(card='n_diffusion_steps', inject='KSampler.0.steps', kind='n'),
        KnobRow(card='lm_cfg_scale', inject='MiniMaxMusic3TextEncode.0.cfg_scale', kind='n'),
    )
